package at.hausgarten.service;
import org.json.*;
public final class PixelMcpEntityWriteTests {
    static JSONObject state() throws Exception {JSONObject s=PixelTunnelContractTests.fixture();s.getJSONObject("master").put("capabilities",SyntheticBusinessData.object().put("entity_compare_and_save",true));s.getJSONObject("master").getJSONArray("customers").getJSONObject(0).put("updated_at","2026-10-12T08:00:00Z");s.getJSONObject("master").getJSONArray("orders").getJSONObject(0).put("updated_at","2026-10-12T08:00:00Z");return s;}
    static JSONObject args(String name)throws Exception {return SyntheticBusinessData.object().put("request_id","entity-test-request").put("name",name);}
    public static void main(String[] ignored)throws Exception { SyntheticBusinessData.verify();
        PixelMcpWriteTests.test("six narrow write tools advertised",()->PixelMcpWriteTests.yes(PixelMcpEntityWriteTools.tools().length()==6));
        PixelMcpWriteTests.test("create customer stable ID and defaults",()->{JSONObject a=args("QA Neue Kundin"),s=state();JSONObject p=PixelMcpEntityWriteTools.prepare("create_customer",a,s,"action-a").getJSONObject("payload");PixelMcpWriteTests.yes(p.getInt("active")==1&&p.getBoolean("_mcp_create")&&p.getString("id").equals(PixelMcpEntityWriteTools.prepare("create_customer",a,s,"action-a").getJSONObject("payload").getString("id")));});
        PixelMcpWriteTests.test("customer duplicate including inactive rejected",()->PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("create_customer",args("Huber alt"),state(),"a")));
        PixelMcpWriteTests.test("protected customer ID rejected",()->PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("create_customer",args("Neu").put("id","qa_c1"),state(),"a")));
        PixelMcpWriteTests.test("customer edit CAS metadata and unchanged ID",()->{JSONObject s=state(),row=s.getJSONObject("master").getJSONArray("customers").getJSONObject(0);JSONObject a=SyntheticBusinessData.object().put("request_id","edit-customer-1").put("customer_id","qa_c1").put("expected_record_hash",PixelMcpWriteTools.hash(PixelMcpEntityWriteTools.recordForHash("customer",row))).put("updates",SyntheticBusinessData.object().put("phone","+43664123"));JSONObject p=PixelMcpEntityWriteTools.prepare("update_customer",a,s,"b").getJSONObject("payload");PixelMcpWriteTests.yes(p.getString("id").equals("qa_c1")&&p.getJSONObject("_mcp_base").has("updated_at"));s.getJSONObject("master").remove("capabilities");PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("update_customer",a,s,"b"));});
        PixelMcpWriteTests.test("create order validates actual customer",()->{JSONObject a=SyntheticBusinessData.object().put("request_id","new-order-test").put("customer_id","qa_c1").put("title","Neue Pflege");PixelMcpEntityWriteTools.prepare("create_order",a,state(),"qa_c");PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("create_order",a.put("customer_id","qa_unknown"),state(),"qa_c"));});
        PixelMcpWriteTests.test("draft creation uses draft number and zero tax",()->{JSONObject a=SyntheticBusinessData.object().put("request_id","new-draft-test").put("customer_id","qa_c1").put("invoice_date","2026-10-12").put("positions",new JSONArray().put(SyntheticBusinessData.object().put("title","Hecke").put("quantity",3).put("price",50)));JSONObject p=PixelMcpEntityWriteTools.prepare("create_invoice_draft",a,state(),"d").getJSONObject("payload");PixelMcpWriteTests.yes(p.getString("invoice_number").startsWith("Entwurf-")&&p.getString("status").equals("Entwurf"));a.getJSONArray("positions").getJSONObject(0).put("tax_rate",20);PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("create_invoice_draft",a,state(),"d"));});
        PixelMcpWriteTests.test("invoice draft reference ownership checked",()->{JSONObject a=SyntheticBusinessData.object().put("request_id","draft-link-test").put("customer_id","qa_c1").put("invoice_date","2026-10-12").put("positions",new JSONArray().put(SyntheticBusinessData.object().put("title","Arbeit").put("quantity",1).put("price",50).put("worklog_id","qa_w2")));PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("create_invoice_draft",a,state(),"e"));});
        PixelMcpWriteTests.test("order edit preserves ownership and rejects stale hash",()->{JSONObject s=state(),row=s.getJSONObject("master").getJSONArray("orders").getJSONObject(0);JSONObject a=SyntheticBusinessData.object().put("request_id","edit-order-request").put("order_id","qa_o1").put("expected_record_hash",PixelMcpWriteTools.hash(PixelMcpEntityWriteTools.recordForHash("order",row))).put("updates",SyntheticBusinessData.object().put("description","Besichtigung"));JSONObject p=PixelMcpEntityWriteTools.prepare("update_order",a,s,"order-edit").getJSONObject("payload");PixelMcpWriteTests.yes(p.getString("id").equals("qa_o1")&&p.getString("customer_id").equals("qa_c1"));a.getJSONObject("updates").put("customer_id","qa_c2");PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("update_order",a,s,"order-edit"));});
        PixelMcpWriteTests.test("draft edit accepts existing calculated positions and blocks issued invoice",()->{JSONObject s=state();JSONObject row=SyntheticBusinessData.object().put("id","qa_i1").put("customer_id","qa_c1").put("status","Entwurf").put("updated_at","2026-10-12T08:00:00Z").put("invoice_date","2026-10-12").put("positions",new JSONArray().put(SyntheticBusinessData.object().put("title","Pflege").put("quantity",3).put("price",50).put("net",150).put("tax",0)));s.getJSONObject("master").getJSONArray("invoices").put(row);JSONObject a=SyntheticBusinessData.object().put("request_id","edit-invoice-request").put("invoice_id","qa_i1").put("expected_record_hash",PixelMcpWriteTools.hash(PixelMcpEntityWriteTools.recordForHash("invoice",row))).put("updates",SyntheticBusinessData.object().put("notes","Zusatz"));JSONObject p=PixelMcpEntityWriteTools.prepare("update_invoice_draft",a,s,"invoice-edit").getJSONObject("payload");PixelMcpWriteTests.yes(p.getDouble("amount")==150&&p.has("_mcp_invoice_positions"));row.put("issued_at","2026-10-12T09:00:00Z");PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("update_invoice_draft",a,s,"invoice-edit"));});
        PixelMcpWriteTests.test("draft uses decimal per-line rounding",()->{JSONObject a=SyntheticBusinessData.object().put("request_id","round-draft-test").put("customer_id","qa_c1").put("invoice_date","2026-10-12").put("positions",new JSONArray().put(SyntheticBusinessData.object().put("title","Pflege").put("quantity",1).put("price",0.005)));JSONObject p=PixelMcpEntityWriteTools.prepare("create_invoice_draft",a,state(),"rounded").getJSONObject("payload");PixelMcpWriteTests.yes(p.getDouble("amount")==0.01);});
PixelMcpWriteTests.test("customer exposes all business fields including custom fields",()->{
            JSONObject properties=PixelMcpEntityWriteTools.schema("create_customer").getJSONObject("properties");
            for(String key:PixelMcpEntityWriteTools.CUSTOMER_FIELDS)PixelMcpWriteTests.yes(properties.has(key));
            PixelMcpWriteTests.yes(!properties.has("id")&&!properties.has("created_at")&&!properties.has("sevdesk_contact_id"));
        });
        PixelMcpWriteTests.test("all customer master data create keeps explicit values",()->{
            JSONObject a=args("QA Alle Felder").put("company","QA Gartenfirma").put("first_name","Anna").put("last_name","Muster").put("street","Gartenweg 4").put("postal_code","9560").put("city","QA Beispielort").put("country","Österreich").put("phone","+43 664 1234567").put("email","qa_603ba7ede2fe@example.invalid").put("notes","Tür links").put("garden_area",120.5).put("sevdesk_customer_number","QA-42").put("active",true).put("custom_fields",SyntheticBusinessData.object().put("Torcode","1234").put("Breite",2.5).put("Hund",true));
            JSONObject p=PixelMcpEntityWriteTools.prepare("create_customer",a,state(),"all-fields").getJSONObject("payload");
            PixelMcpWriteTests.yes(p.getString("city").equals("QA Beispielort")&&p.getDouble("garden_area")==120.5&&p.getJSONObject("custom_fields").getDouble("Breite")==2.5&&p.getString("notes").equals("Tür links"));
        });
        PixelMcpWriteTests.test("garden area can be explicitly cleared",()->PixelMcpWriteTests.yes(PixelMcpEntityWriteTools.prepare("create_customer",args("QA Fläche").put("garden_area",JSONObject.NULL),state(),"nullable").getJSONObject("payload").isNull("garden_area")));
        PixelMcpWriteTests.test("invalid email rejected without guessing correction",()->PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("create_customer",args("QA Email").put("email","kein-email"),state(),"invalid-email")));
        PixelMcpWriteTests.test("blank optional email remains allowed",()->PixelMcpEntityWriteTools.prepare("create_customer",args("QA Ohne Email").put("email",""),state(),"empty-email"));
        PixelMcpWriteTests.test("normalized customer name duplicate rejected",()->{JSONObject s=state();String existing=s.getJSONObject("master").getJSONArray("customers").getJSONObject(0).getString("name");PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("create_customer",args("  "+existing.toUpperCase(java.util.Locale.ROOT)+"  "),s,"normalized-name"));});
        PixelMcpWriteTests.test("company duplicate recognized",()->{JSONObject s=state();s.getJSONObject("master").getJSONArray("customers").getJSONObject(0).put("company","QA Garten");PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("create_customer",args("Anderer Name").put("company","qa garten"),s,"company-duplicate"));});
        PixelMcpWriteTests.test("first and last name duplicate recognized",()->{JSONObject s=state();s.getJSONObject("master").getJSONArray("customers").getJSONObject(0).put("first_name","Anna").put("last_name","Muster");PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("create_customer",args("Neue Firma").put("first_name","Anna").put("last_name","Muster"),s,"full-name"));});
        PixelMcpWriteTests.test("arbitrary identity and duplicate bypass rejected",()->{
            PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("create_customer",args("Neu").put("allow_duplicate",true),state(),"bypass"));
            PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("create_customer",args("Neu").put("sevdesk_contact_id","invented"),state(),"external-id"));
        });
        PixelMcpWriteTests.test("custom fields reject nested objects",()->PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("create_customer",args("Nested").put("custom_fields",SyntheticBusinessData.object().put("Notiz",SyntheticBusinessData.object().put("x",1))),state(),"nested")));
        PixelMcpWriteTests.test("custom fields reject prototype pollution keys",()->PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("create_customer",args("Prototype").put("custom_fields",SyntheticBusinessData.object().put("__proto__","x")),state(),"prototype")));
        PixelMcpWriteTests.test("customer update preserves created time and external identity",()->{
            JSONObject s=state(),old=s.getJSONObject("master").getJSONArray("customers").getJSONObject(0);old.put("created_at","2020-01-01T00:00:00Z").put("sevdesk_contact_id","existing-sevdesk");
            JSONObject a=SyntheticBusinessData.object().put("request_id","preserve-customer").put("customer_id","qa_c1").put("expected_record_hash",PixelMcpWriteTools.hash(PixelMcpEntityWriteTools.recordForHash("customer",old))).put("updates",SyntheticBusinessData.object().put("notes","Neue Notiz"));
            JSONObject p=PixelMcpEntityWriteTools.prepare("update_customer",a,s,"preserve").getJSONObject("payload");
            PixelMcpWriteTests.yes(p.getString("created_at").equals("2020-01-01T00:00:00Z")&&p.getString("sevdesk_contact_id").equals("existing-sevdesk")&&p.getString("id").equals("qa_c1"));
        });
        PixelMcpWriteTests.test("custom update merges old JSON text instead of replacing unseen fields",()->{
            JSONObject s=state(),master=s.getJSONObject("master"),old=master.getJSONArray("customers").getJSONObject(0);master.getJSONObject("capabilities").put("customer_custom_fields_compare_and_save",true);old.put("custom_fields","{\"Torcode\":\"1234\",\"Hinweis\":\"Behalten\"}");
            JSONObject a=SyntheticBusinessData.object().put("request_id","merge-custom-fields").put("customer_id","qa_c1").put("expected_record_hash",PixelMcpWriteTools.hash(PixelMcpEntityWriteTools.recordForHash("customer",old))).put("updates",SyntheticBusinessData.object().put("custom_fields",SyntheticBusinessData.object().put("Torcode","4321")));
            JSONObject p=PixelMcpEntityWriteTools.prepare("update_customer",a,s,"merge").getJSONObject("payload");
            PixelMcpWriteTests.yes(p.getJSONObject("custom_fields").getString("Hinweis").equals("Behalten")&&p.getJSONObject("_mcp_base").getJSONObject("custom_fields").getString("Torcode").equals("1234"));
            master.getJSONObject("capabilities").remove("customer_custom_fields_compare_and_save");PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("update_customer",a,s,"merge"));
        });
        PixelMcpWriteTests.test("customer fields never expose a delete operation",()->{for(String name:PixelMcpEntityWriteTools.NAMES)PixelMcpWriteTests.yes(!name.contains("delete"));});
        PixelMcpWriteTests.test("customer updates require hash and reject unknown ID",()->{
            PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("update_customer",SyntheticBusinessData.object().put("request_id","no-hash-customer").put("customer_id","qa_c1").put("updates",SyntheticBusinessData.object().put("phone","123")),state(),"no-hash"));
            PixelMcpWriteTests.bad(()->PixelMcpEntityWriteTools.prepare("update_customer",SyntheticBusinessData.object().put("request_id","unknown-customer").put("customer_id","qa_missing").put("expected_record_hash","bad").put("updates",SyntheticBusinessData.object().put("phone","123")),state(),"qa_unknown"));
        });
        PixelMcpWriteTests.test("read customer lists editable and protected fields",()->{JSONObject result=new PixelMcpReadTools(()->state()).call("get_customer",SyntheticBusinessData.object().put("customer_id","qa_c1"));PixelMcpWriteTests.yes(result.getJSONArray("editable_fields").toString().contains("custom_fields")&&result.getJSONArray("read_only_fields").toString().contains("created_at")&&result.has("record_hash"));});
        PixelMcpWriteTests.test("read-only server rejects customer writes",()->PixelMcpWriteTests.bad(()->new PixelMcpReadTools(()->state()).call("create_customer",args("QA Disabled"))));
        PixelMcpWriteTests.test("write annotations accurately describe customer updates",()->{JSONArray tools=PixelMcpEntityWriteTools.tools();PixelMcpWriteTests.yes(!tools.getJSONObject(0).getJSONObject("annotations").getBoolean("readOnlyHint")&&!tools.getJSONObject(0).getJSONObject("annotations").getBoolean("destructiveHint")&&tools.getJSONObject(1).getJSONObject("annotations").getBoolean("destructiveHint"));});
        System.out.println("PASS total="+PixelMcpWriteTests.count+" entity write tests");
    }
}
